    # N % A == 0 and N % B == 0
    # That is, N is a common multiple of A and B.
    # The minimum such N is the Least Common Multiple (LCM).

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

